   395→}
   396→
   397→/* Smooth border transition for selection */
   398→.carousel-card-border {
   399→  transition: border-color 0.3s ease, box-shadow 0.3s ease;
   400→}
   401→
   402→/* Hide scrollbar for selected items row */
   403→.hide-scrollbar {
   404→  -ms-overflow-style: none;
   405→  scrollbar-width: none;
   406→}
   407→
   408→.hide-scrollbar::-webkit-scrollbar {
   409→  display: none;
   410→}
   411→
   412→/* Style card utility for uniform height and styling */
   413→.style-card {
   414→  height: 320px;
   415→  display: flex;
   416→  flex-direction: column;
   417→}
   418→
   419→.style-card-image {
   420→  height: 220px;
   421→  flex-shrink: 0;
   422→}
   423→
   424→.style-card-content {
   425→  height: 100px;
   426→  flex-shrink: 0;
   427→}
   428→
   429→/* Line clamp utilities for text truncation */
   430→.line-clamp-2 {
   431→  display: -webkit-box;
   432→  -webkit-line-clamp: 2;
   433→  -webkit-box-orient: vertical;
   434→  overflow: hidden;
   435→}
   436→
   437→.line-clamp-3 {
   438→  display: -webkit-box;
   439→  -webkit-line-clamp: 3;
   440→  -webkit-box-orient: vertical;
   441→  overflow: hidden;
   442→}
   443→
   444→/* 3D Center-Focus Carousel Styles */
   445→.carousel-perspective {
   446→  perspective: 1000px;
   447→}
   448→
   449→.carousel-slide-3d {
   450→  transform-origin: center center;
   451→  will-change: transform, opacity;
   452→}
   453→
   454→/* Center card enhanced shadow */
   455→.carousel-slide-3d button.shadow-lg {
   456→  box-shadow: 0 10px 25px -5px rgba(0, 0, 0, 0.15), 0 8px 10px -6px rgba(0, 0, 0, 0.1);
   457→}
