// Calculate scale, opacity, and translateZ based on distance from center
// Enhanced center-focus effect to match design mockups
const getSlideStyles = (index: number) => {
  const distance = Math.abs(index - selectedIndex);
  // More dramatic scale: center 1.0, adjacent 0.7, further 0.55
  const scale = distance === 0 ? 1 : Math.max(0.55, 1 - distance * 0.3);
  // Enhanced opacity contrast: center 1.0, adjacent 0.6, further 0.4
  const opacity = distance === 0 ? 1 : Math.max(0.4, 1 - distance * 0.4);
  // 3D depth with translateZ: center forward, sides recede
  const translateZ = distance === 0 ? 50 : -50 - distance * 20;
  return {
    transform: `scale(${scale}) translateZ(${translateZ}px)`,
    opacity,
    transition: 'transform 0.4s cubic-bezier(0.4, 0, 0.2, 1), opacity 0.4s cubic-bezier(0.4, 0, 0.2, 1)',
  };
};

// Dynamic width calculation based on center position
const getSlideWidth = (index: number) => {
  const isCentered = index === selectedIndex;
  // Center card: ~70% viewport width (280px on mobile), sides: smaller
  return isCentered ? 'calc(70vw)' : '180px';
};

