                        ${isCentered ? 'shadow-xl' : 'shadow-none'}
                      `}
                    >
                      {/* Style Image - ~70% of card height */}
                      <div className={`w-full overflow-hidden rounded-t-2xl relative flex-shrink-0 ${isCentered ? 'h-[280px] md:h-[320px]' : 'h-[200px]'}`}>
                        {style.imageUrl && !failedImages.has(style.id) ? (
                          <img
                            src={style.imageUrl}
                            alt={`${style.name} style`}
                            loading="lazy"
                            onError={() => handleImageError(style.id)}
                            className="absolute inset-0 w-full h-full object-cover object-top"
                          />
                        ) : (
                          <div className="absolute inset-0 bg-gradient-to-br from-gray-100 to-gray-200 flex items-center justify-center">
                            <span className="text-4xl">👗</span>
                          </div>
                        )}
                      </div>
                      {/* Style Text Content - ~30% of card */}
                      <div className={`text-center flex-1 flex flex-col justify-start ${isCentered ? 'p-4' : 'p-2'}`}>
                        <h3 className={`font-semibold text-[var(--onboarding-primary)] ${isCentered ? 'text-base' : 'text-sm'}`}>
                          {style.name} · {style.description}
                        </h3>
                        <p className={`text-gray-600 mt-1 leading-relaxed ${isCentered ? 'text-xs line-clamp-3' : 'text-[10px] line-clamp-2'}`}>
                          {style.cardDescription}
                        </p>
                      </div>
                    </button>
                  </div>
                );
              })}
            </div>
          </div>

          {/* Next Button - Circular Red, Bottom Center */}
          <div className="flex justify-center pt-6">
            <Button
              onClick={handleNext}
              disabled={selectedStyles.length === 0}
              className="w-14 h-14 rounded-full bg-[var(--onboarding-primary)] hover:bg-[var(--onboarding-primary-hover)] text-white disabled:bg-gray-300 disabled:cursor-not-allowed"
            >
              <ArrowRight className="w-6 h-6" />
            </Button>
          </div>
        </div>
      </div>
    </div>
  );
}

